31	/**
32	 * Text a call is writing or printing right now: the command or file content a model is still writing, or the end of what a
33	 * running command has printed. Bounded, monospace, with its own scroll area that follows the newest text until the reader
34	 * scrolls up to read, and quiet for a screen reader (the log is `aria-live="off"`; this is a region to move into, not news).
35	 */
36	function LiveText({ text, label }: { text: string; label: string }) {
37	  const box = useRef<HTMLPreElement>(null);
38	  const following = useRef(true);
39	  useLayoutEffect(() => {
40	    const element = box.current;
41	    if (element && following.current) element.scrollTop = element.scrollHeight;
42	  }, [text]);
43	  if (!text) return null;
44	  return <pre ref={box} tabIndex={0} role="region" aria-label={label} data-live-text
45	    onScroll={(event) => { const element = event.currentTarget; following.current = element.scrollHeight - element.scrollTop - element.clientHeight < 24; }}
46	    className="mt-2 max-h-48 max-w-full overflow-auto overscroll-contain whitespace-pre rounded-lg border bg-muted/40 p-3 font-mono text-xs leading-5 text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring/60">{text}</pre>;
