50	const DraftRow = memo(function DraftRow({ call }: { call: LiveToolView }) {
51	  const shown = describeDraft(call.name, call.detail);
52	  const showing = !!shown;
53	  useEffect(() => { if (showing) draftedCalls.add(call.callId); }, [showing, call.callId]);
