74	export const EntryRow = memo(function EntryRow({ taskId, entry, current, animate, output }: { taskId: string; entry: RowEntry; current: boolean; animate: boolean; output?: string }) {
75	  const panelId = useId();
76	  const expandable = entry.kind === "group" || (entry.kind === "call" && entry.detailable);
77	  const [open, toggle] = useDisclosure(disclosureKey(taskId, entry.id), false);
78	  // A call shown while it was being written has entered already: its real row takes the draft's place without a second entrance.
79	  const drafted = entry.kind === "call" && !!entry.callId && draftedCalls.has(entry.callId);
80	  const base = `${animate && !drafted ? "message-in " : ""}min-w-0`;
81	  const meta = entry.kind === "milestone"
82	    ? { icon: "success" as StatusIcon, tone: "success" as Tone, label: entry.label, detail: undefined, outcome: "completed" }
83	    : { icon: entry.icon, tone: entry.tone, label: entry.label, detail: entry.kind === "call" ? entry.detail : undefined, outcome: entry.outcome };
84	  const shimmer = current && entry.kind === "call" && entry.outcome === "running";
85	  const hooks = { "data-activity-entry": entry.kind, "data-outcome": meta.outcome, "data-tone": meta.tone, ...(entry.kind !== "milestone" ? { "data-tool": entry.tool } : {}) };
86	  if (!expandable) {
87	    // A running command shows what it has printed so far under its row; the finished row opens the saved output instead.
88	    return <li className={base} {...hooks}>
89	      <div className="flex items-center gap-2.5">
90	        <Glyph icon={meta.icon} tone={meta.tone} current={current} tool={entry.kind !== "milestone" ? entry.tool : undefined} />
91	        <Words label={meta.label} detail={meta.detail} shimmer={shimmer} />
92	      </div>
93	      {output ? <LiveText text={output} label="Live output" /> : null}
94	    </li>;
95	  }
96	  return <li className={base} {...hooks}>
97	    <button type="button" aria-expanded={open} aria-controls={panelId} data-scroll-anchor-toggle className={rowButton} onClick={toggle}>
98	      <Glyph icon={meta.icon} tone={meta.tone} current={current} tool={entry.tool} />
99	      <Words label={meta.label} detail={meta.detail} shimmer={shimmer} />
100	      {chevron(open)}
101	    </button>
102	    <div id={panelId} hidden={!open} className="mt-2 ml-2 border-l pl-4">
103	      {open ? (entry.kind === "group"
104	        ? <ul className="space-y-2" aria-label="Actions in this group">{entry.calls.map((call) => <EntryRow key={call.key} taskId={taskId} entry={call} current={false} animate={false} />)}</ul>
105	        : entry.kind === "call" && entry.toolCallId ? <ToolDetailPanel key={`${taskId}:${entry.toolCallId}`} taskId={taskId} toolCallId={entry.toolCallId} /> : null) : null}
