126	function StatusRow({ icon = "running", current, label, children, animate = false, fade = false }: { icon?: StatusIcon; current: boolean; label: string; children?: ReactNode; animate?: boolean; fade?: boolean }) {
127	  // Work in progress ("Thinking", "Stopping") is the shimmering words alone; only a warning keeps a glyph to mark it apart.
