139	type TimelineProps = {
140	  /** The task the entries belong to: disclosure choices are remembered per task. */
141	  taskId?: string;
142	  entries: readonly ActivityEntry[];
143	  /** The run is still going: a status line ("Thinking") may show. */
144	  live?: boolean;
145	  /** Nothing new has shown for a while. */
146	  quiet?: boolean;
147	  fallback?: string;
148	  /** Text still being written (a progress note, then the answer). */
149	  tail?: ReactNode;
150	  /** Trouble reaching the server, shown inside the timeline. */
151	  notice?: TimelineNotice | null;
152	  onRetry?: () => void;
153	  stopping?: boolean;
154	  /** Rows play their entrance. Off for activity that is loaded or was already shown, so nothing replays. */
155	  animate?: boolean;
156	  /** The one short sentence a screen reader hears (never the streamed words). Omitted: no status region. */
157	  announcement?: string;
158	  /** The run is over: its steps fold into the closed "Worked · 41s · N steps" disclosure, the same one the saved answer shows. */
159	  fold?: boolean;
160	  durationMs?: number | null;
161	  /** Calls the agent stopped before, waiting for an Approve / Decline. */
162	  approvals?: readonly PendingApproval[];
163	  /** The "Thinking" line plays its entrance (only the indicator shown the moment a message is sent). */
164	  statusEnters?: boolean;
165	  /** The tool call the live row shows: being written by the model, or running and printing. */
166	  liveTool?: LiveToolView | null;
167	};
168	
169	function renderSection(section: Section, taskId: string, current: string | null, animate: boolean, extra: ReactNode, outputFor: { entryId: string; text: string } | null, waiting: ReadonlySet<string>) {
170	  switch (section.kind) {
171	    case "note": return <NoteBlock key={section.id} text={section.entry.text} />;
172	    case "phase": return <PhaseHeading key={section.id} entry={section.entry} />;
173	    case "rows": return <ul key={section.id} className="space-y-2 text-[15px] leading-6 text-muted-foreground" aria-label="Steps">
174	      {chunkRows(section.entries).map((chunk) => chunk.kind === "subagents"
175	        ? <SubagentFleet key={chunk.key} taskId={taskId} calls={chunk.calls} animate={animate} waiting={waiting} />
176	        : <EntryRow key={chunk.key} taskId={taskId} entry={chunk.entry} current={chunk.entry.id === current} animate={animate} output={outputFor?.entryId === chunk.entry.id ? outputFor.text : undefined} />)}
177	      {extra}
178	    </ul>;
179	  }
180	}
