182	/**
183	 * What the agent said and did, oldest first, as it happened: its notes in the person's own reading voice and one line per step.
184	 * While `live`, one status line ("Thinking") appears only when nothing else shows that work is going on: no step is running and
185	 * no text is being written (`tail`). Straight after the start of a run that is immediately; once there is something to read,
186	 * only when the run has been `quiet` for a while, so it never competes with text the agent has just written.
187	 *
188	 * The log itself is `aria-live="off"`: streaming text and growing rows would be read out word by word. A separate polite status
189	 * says only what changed in the run (`announcement`).
190	 */
191	export function Timeline({ taskId = "", entries, live = false, quiet = false, fallback = "Thinking", tail, notice = null, onRetry, stopping = false, animate = true, announcement, fold = false, durationMs, approvals = [], statusEnters = false, liveTool = null }: TimelineProps) {
192	  const sections = useMemo(() => sectionsOf(entries), [entries]);
193	  const callId = useMemo(() => currentCallId(entries), [entries]);
194	  // Subagents that have a question for the person, and whose each question is.
195	  const subagents = useMemo(() => subagentsByRun(entries), [entries]);
196	  const waiting = useMemo(() => new Set(approvals.flatMap((approval) => approval.agentRunId ? [approval.agentRunId] : [])), [approvals]);
197	  const nothingYet = !entries.some((entry) => entry.kind !== "phase");
198	  // A call being written, or a running command's output. Not shown once the run is folded away into its summary.
199	  const placement = useMemo(() => fold ? null : placeLiveTool(entries, liveTool, approvals.length > 0), [fold, entries, liveTool, approvals.length]);
200	  const draftRow = placement?.kind === "draft" ? <DraftRow key={`draft:${placement.call.callId}`} call={placement.call} /> : null;
201	  const outputFor = placement?.kind === "output" ? placement : null;
202	  // A call being written is work in progress too: "Thinking" would say nothing is happening while its text is arriving.
203	  const running = callId !== null || stopping || !!draftRow;
204	  // A connection notice stands in for "Thinking" when nothing else shows life; otherwise it sits quietly under the rest.
205	  // A waiting approval card is the sign of life: "Thinking" would say the agent is busy while it waits for the person.
206	  const status = live && !tail && !running && !notice && !approvals.length && (nothingYet || quiet);
207	  const noticeLeads = !!notice && !tail && !running && notice.kind !== "halted" && notice.kind !== "failed";
208	  const current = stopping ? "stopping" : callId;
209	  const last = sections[sections.length - 1];
210	  const stoppingRow = stopping ? <StatusRow key="stopping" current label="Stopping" animate /> : null;
211	  // What follows the last list of steps: the call being written, then "Stopping". Each opens a list of its own after a note or heading.
212	  const trailing = draftRow || stoppingRow ? <>{draftRow}{stoppingRow}</> : null;
213	  return <>
214	    <div className="flex min-w-0 flex-col gap-3" role="log" aria-live="off" aria-label="Agent activity" data-activity-log data-live={live ? "true" : undefined}>
215	      {fold ? <ActivityDisclosure taskId={taskId} entries={entries} durationMs={durationMs} className="" />
216	        : sections.map((section, index) => renderSection(section, taskId, current, animate, section.kind === "rows" && index === sections.length - 1 ? trailing : null, outputFor, waiting))}
217	      {trailing && last?.kind !== "rows" ? <ul className="space-y-2 text-[15px] leading-6 text-muted-foreground" aria-label="Steps">{trailing}</ul> : null}
218	      {approvals.map((approval) => <ApprovalCard key={approval.id} approval={approval} source={approvalSource(approval.agentRunId, subagents)} />)}
219	      {tail}
220	      {notice ? <ul className="text-[15px] leading-6 text-muted-foreground" aria-label="Connection" data-activity-notice={notice.kind}>
221	        <StatusRow icon={noticeLeads ? "running" : notice.kind === "reconnecting" || notice.kind === "catching_up" ? "unknown" : "warning"} current={noticeLeads} label={notice.text} animate>
222	          {notice.kind === "failed" && onRetry ? <button type="button" onClick={onRetry} className={`ml-1 shrink-0 rounded px-1 font-medium text-foreground underline underline-offset-4 [@media(pointer:coarse)]:min-h-11 ${toggleClass}`}>Retry</button> : null}
223	        </StatusRow>
224	      </ul> : null}
225	      {status ? <ul className="text-[15px] leading-6 text-muted-foreground" aria-label="Status"><StatusRow current label={fallback} animate={statusEnters} fade={!statusEnters && !nothingYet} /></ul> : null}
226	    </div>
227	    {announcement !== undefined ? <span role="status" aria-live="polite" className="sr-only" data-activity-status>{announcement}</span> : null}
228	  </>;
229	}
