18	/** Bounded, monospace text with its own scroll area, a copy control and a notice when the server clipped it. */
19	function LogBlock({ label, text, diff = false }: { label: string; text: ToolDetailText; diff?: boolean }) {
20	  const notice = truncationNotice(text);
21	  return <div className="min-w-0" data-detail-log={label.toLowerCase()}>
22	    <div className="flex min-h-8 items-center justify-between text-xs text-muted-foreground">
